'use client';

import { useId, useRef, useState } from 'react';
import './revenue-dashboard-hero.css';

export type RevenueDashboardTransaction = {
  id: string;
  customer: string;
  /** UTC calendar date in YYYY-MM-DD format. */
  date: string;
  /** A nonnegative payment in major currency units; for example, 129.50. */
  amount: number;
  channel: string;
};

export type RevenueDashboardHeroProps = {
  transactions: RevenueDashboardTransaction[];
  brand?: string;
  title?: string;
  description?: string;
  actionLabel?: string;
  actionHref?: string;
  currency?: string;
  /** Inclusive range end. Defaults to the latest valid transaction date. */
  endDate?: string;
  defaultRange?: 7 | 30;
  className?: string;
};

type Payment = RevenueDashboardTransaction & { day: number };
const DAY = 86_400_000;

function calendarDay(value: string): number | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const [year, month, date] = value.split('-').map(Number);
  const day = Date.UTC(year, month - 1, date);
  return Number.isFinite(day) && new Date(day).toISOString().slice(0, 10) === value ? day : null;
}

function shortDate(day: number) {
  return new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' }).format(day);
}

function LedgerMark({ className = '' }: { className?: string }) {
  return <svg className={className} viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M5 5h7v18H5V5Zm11 0h7v7h-7V5Zm0 11h7v7h-7v-7Z" fill="currentColor"/></svg>;
}

/** A SaaS hero with one filtered source of truth for its metrics, chart and payments. */
export function RevenueDashboardHero({
  transactions,
  brand = 'Ledger',
  title = 'Know where revenue comes from.',
  description = 'Track collected payments, compare channels, and follow every number back to a transaction.',
  actionLabel = 'Explore the dashboard',
  actionHref,
  currency = 'USD',
  endDate,
  defaultRange = 30,
  className = '',
}: RevenueDashboardHeroProps) {
  const uid = useId();
  const dashboardRef = useRef<HTMLDivElement>(null);
  const [range, setRange] = useState<7 | 30>(defaultRange === 7 ? 7 : 30);
  const [selectedChannel, setSelectedChannel] = useState<string | null>(null);
  const seenIds = new Set<string>();
  const payments: Payment[] = [];
  for (const transaction of transactions) {
    const day = calendarDay(transaction.date);
    if (day === null || !Number.isFinite(transaction.amount) || transaction.amount < 0 || !transaction.id || seenIds.has(transaction.id)) continue;
    seenIds.add(transaction.id);
    payments.push({ ...transaction, amount: Math.round(transaction.amount * 100) / 100, channel: transaction.channel.trim() || 'Other', day });
  }
  const channels = [...new Set(payments.map(payment => payment.channel))].sort();
  const channel = selectedChannel !== null && channels.includes(selectedChannel) ? selectedChannel : null;
  const latestDay = payments.reduce<number | null>((latest, payment) => latest === null ? payment.day : Math.max(latest, payment.day), null);
  const rangeEnd = (endDate ? calendarDay(endDate) : null) ?? latestDay;
  const rangeStart = rangeEnd === null ? null : rangeEnd - (range - 1) * DAY;
  const filtered = payments.filter(payment => rangeStart !== null && rangeEnd !== null && payment.day >= rangeStart && payment.day <= rangeEnd && (channel === null || payment.channel === channel)).sort((a, b) => b.day - a.day || a.id.localeCompare(b.id));
  const total = filtered.reduce((sum, payment) => sum + Math.round(payment.amount * 100), 0) / 100;
  const average = filtered.length ? total / filtered.length : 0;
  const daily = rangeStart === null ? [] : Array.from({ length: range }, (_, index) => {
    const day = rangeStart + index * DAY;
    return { day, amount: filtered.filter(payment => payment.day === day).reduce((sum, payment) => sum + Math.round(payment.amount * 100), 0) / 100 };
  });
  let currencyCode = currency;
  try { new Intl.NumberFormat('en-US', { style: 'currency', currency: currencyCode }); } catch { currencyCode = 'USD'; }
  const money = (value: number, precise = false) => new Intl.NumberFormat('en-US', { style: 'currency', currency: currencyCode, minimumFractionDigits: precise ? 2 : 0, maximumFractionDigits: 2 }).format(value);
  const compactMoney = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: currencyCode, notation: 'compact', maximumFractionDigits: 1 }).format(value);
  const chartMax = Math.max(1, ...daily.map(day => day.amount));
  const chartWidth = 600;
  const chartHeight = 130;
  const slotWidth = chartWidth / Math.max(daily.length, 1);
  const dateRange = rangeStart !== null && rangeEnd !== null ? `${shortDate(rangeStart)} – ${shortDate(rangeEnd)}, ${new Date(rangeEnd).getUTCFullYear()}` : 'No transaction dates';

  function exploreDashboard() {
    dashboardRef.current?.focus({ preventScroll: true });
    dashboardRef.current?.scrollIntoView({ block: 'nearest', behavior: 'auto' });
  }

  return <section className={`ac-revenue-hero ${className}`.trim()} aria-labelledby={`${uid}-title`}>
    <div className="ac-revenue-hero-shell">
      <header className="ac-revenue-masthead"><span className="ac-revenue-brand"><LedgerMark/>{brand}</span><span className="ac-revenue-masthead-label">Revenue analytics</span></header>
      <div className="ac-revenue-layout">
        <div className="ac-revenue-introduction">
          <p className="ac-revenue-eyebrow"><span aria-hidden="true"/>Payment analytics</p>
          <h2 id={`${uid}-title`}>{title}</h2>
          {description && <p className="ac-revenue-description">{description}</p>}
          {actionHref ? <a className="ac-revenue-action" href={actionHref}>{actionLabel}<span aria-hidden="true">↗</span></a> : <button type="button" className="ac-revenue-action" onClick={exploreDashboard}>{actionLabel}<span aria-hidden="true">↗</span></button>}
        </div>
        <div className="ac-revenue-product-field">
          <div className="ac-revenue-field-label"><span>Revenue workspace</span><span aria-hidden="true">↙</span></div>
          <div className="ac-revenue-dashboard" ref={dashboardRef} tabIndex={-1} role="region" aria-label={`${brand} interactive revenue dashboard`}>
            <div className="ac-revenue-app-bar"><span><LedgerMark/>{brand}<b> / </b>Overview</span><span className="ac-revenue-preview-label">Product preview</span></div>
            <div className="ac-revenue-app-content">
              <div className="ac-revenue-app-heading"><div><p>Reporting</p><h3>Revenue overview</h3></div><span className="ac-revenue-currency">{currencyCode}</span></div>
              <div className="ac-revenue-controls">
                <div className="ac-revenue-range" role="group" aria-label="Revenue date range">{([7, 30] as const).map(days => <button key={days} type="button" aria-pressed={range === days} onClick={() => setRange(days)}>{days} days</button>)}</div>
                <label className="ac-revenue-channel"><span className="ac-revenue-sr">Payment channel</span><select value={channel ?? ''} onChange={event => setSelectedChannel(event.target.value || null)}><option value="">All channels</option>{channels.map(value => <option key={value} value={value}>{value}</option>)}</select><svg aria-hidden="true" viewBox="0 0 12 12" fill="none"><path d="m3 4.5 3 3 3-3" stroke="currentColor" strokeWidth="1.3"/></svg></label>
              </div>
              <div className="ac-revenue-metrics" aria-live="polite" aria-atomic="true"><div className="ac-revenue-total"><span>Collected revenue</span><strong>{money(total)}</strong></div><div><span>Payments</span><strong>{filtered.length}</strong></div><div><span>Average payment</span><strong>{money(average)}</strong></div></div>
              <div className="ac-revenue-chart-heading"><h4>Daily collections</h4><span>{dateRange}</span></div>
              <div className="ac-revenue-chart-wrap">
                <div className="ac-revenue-y-axis" aria-hidden="true"><span>{compactMoney(chartMax)}</span><span>{compactMoney(chartMax / 2)}</span><span>{money(0)}</span></div>
                <div className="ac-revenue-chart"><svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} preserveAspectRatio="none" role="img" aria-labelledby={`${uid}-chart-title ${uid}-chart-description`}>
                  <title id={`${uid}-chart-title`}>{`Daily collected revenue in ${currencyCode}`}</title><desc id={`${uid}-chart-description`}>{`${money(total)} from ${filtered.length} payments. ${dateRange}. ${channel ?? 'All channels'}. Daily values follow in a table.`}</desc>
                  {[0, 0.5, 1].map(position => <line key={position} x1="0" x2={chartWidth} y1={position * (chartHeight - 4) + 2} y2={position * (chartHeight - 4) + 2} className="ac-revenue-grid-line"/>)}
                  {daily.map((day, index) => <rect key={day.day} x={index * slotWidth + slotWidth * .17} y={chartHeight - 2 - day.amount / chartMax * (chartHeight - 4)} width={slotWidth * .66} height={day.amount / chartMax * (chartHeight - 4)} rx={Math.min(3, slotWidth * .13)} className="ac-revenue-chart-bar"><title>{`${shortDate(day.day)}: ${money(day.amount, true)}`}</title></rect>)}
                </svg><div className="ac-revenue-x-axis" aria-hidden="true">{daily.length ? <><span>{shortDate(daily[0].day)}</span><span>{shortDate(daily[Math.floor((daily.length - 1) / 2)].day)}</span><span>{shortDate(daily[daily.length - 1].day)}</span></> : <span>No dates available</span>}</div></div>
              </div>
              <div className="ac-revenue-sr"><table><caption>Daily collected revenue: {dateRange}, {channel ?? 'all channels'}</caption><thead><tr><th scope="col">Date</th><th scope="col">Revenue ({currencyCode})</th></tr></thead><tbody>{daily.map(day => <tr key={day.day}><th scope="row">{new Date(day.day).toISOString().slice(0, 10)}</th><td>{money(day.amount, true)}</td></tr>)}</tbody></table></div>
              <div className="ac-revenue-transactions-heading"><h4>Transactions</h4><span>{filtered.length} {filtered.length === 1 ? 'payment' : 'payments'}</span></div>
              <div className="ac-revenue-transaction-scroll" tabIndex={filtered.length > 3 ? 0 : undefined} role="region" aria-label="Filtered payments, scroll for all transactions">
                <table className="ac-revenue-transactions"><caption className="ac-revenue-sr">Payments included in the revenue total</caption><thead><tr><th scope="col">Customer</th><th scope="col">Date</th><th scope="col">Amount</th></tr></thead><tbody>{filtered.map(payment => <tr key={payment.id}><th scope="row"><span className="ac-revenue-customer-avatar" aria-hidden="true">{payment.customer.trim().slice(0, 1) || '·'}</span><span>{payment.customer || 'Unnamed customer'}<small>{payment.channel}</small></span></th><td><time dateTime={payment.date}>{shortDate(payment.day)}</time></td><td>{money(payment.amount, true)}</td></tr>)}</tbody></table>
                {filtered.length === 0 && <p className="ac-revenue-empty">No payments in this date range{channel ? ` for ${channel}` : ''}.</p>}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>;
}

.ac-revenue-hero {
  --ac-revenue-ink: #11121b;
  --ac-revenue-text: #f2f3fc;
  --ac-revenue-muted: #bec0d0;
  --ac-revenue-accent: #b9b8ff;
  --ac-revenue-chart: #6253e8;
  --ac-revenue-field: #c6c5ff;
  container: ac-revenue / inline-size;
  width: 100%;
  background: var(--ac-revenue-ink);
  color: var(--ac-revenue-text);
  font-family: Arial, Helvetica, sans-serif;
  text-align: left;
  isolation: isolate;
}
.ac-revenue-hero *, .ac-revenue-hero *::before, .ac-revenue-hero *::after { box-sizing: border-box; }
.ac-revenue-hero button, .ac-revenue-hero select, .ac-revenue-hero a { -webkit-tap-highlight-color: transparent; font: inherit; }
.ac-revenue-hero button, .ac-revenue-hero select { cursor: pointer; }
.ac-revenue-hero button { appearance: none; }
.ac-revenue-hero h2, .ac-revenue-hero h3, .ac-revenue-hero h4, .ac-revenue-hero p { margin: 0; }
.ac-revenue-hero-shell { width: min(100%, 1740px); margin: auto; padding: 0 clamp(24px, 3.2cqi, 64px) clamp(24px, 3cqi, 48px); }
.ac-revenue-masthead { display: flex; align-items: center; justify-content: space-between; min-height: 81px; gap: 20px; }
.ac-revenue-brand { display: inline-flex; align-items: center; gap: 9px; font-size: 23px; font-weight: 650; letter-spacing: -.055em; }
.ac-revenue-brand svg { width: 27px; height: 27px; color: var(--ac-revenue-accent); }
.ac-revenue-masthead-label { color: #b8bac9; font-size: 12px; letter-spacing: -.01em; }
.ac-revenue-layout { display: grid; grid-template-columns: minmax(0, .82fr) minmax(0, 1.18fr); gap: clamp(24px, 3.3cqi, 58px); align-items: stretch; }
.ac-revenue-introduction { align-self: start; padding: 68px 0 40px; min-width: 0; }
.ac-revenue-eyebrow { display: flex; align-items: center; gap: 8px; color: var(--ac-revenue-accent); font-size: 11px; line-height: 1.5; letter-spacing: .015em; }
.ac-revenue-eyebrow > span { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.ac-revenue-introduction h2 { max-width: 12ch; margin: 23px 0 22px; color: var(--ac-revenue-text); font-size: clamp(48px, 5.2cqi, 86px); font-weight: 500; line-height: 1.025; letter-spacing: -.065em; overflow-wrap: anywhere; text-wrap: balance; }
.ac-revenue-description { max-width: 31ch; color: var(--ac-revenue-muted); font-size: clamp(14px, 1.05cqi, 17px); line-height: 1.65; letter-spacing: -.015em; }
.ac-revenue-action { display: inline-flex; justify-content: space-between; align-items: center; gap: 29px; min-height: 48px; margin-top: 29px; padding: 0 17px; border: 1px solid transparent; border-radius: 7px; background: var(--ac-revenue-accent); color: #17162a; text-decoration: none; font-size: 12px !important; font-weight: 600 !important; line-height: 1.4; transition: background .18s ease, transform .18s ease; }
.ac-revenue-action > span { font-size: 20px; font-weight: 400; }
.ac-revenue-action:hover { background: #d2d1ff; transform: translateY(-2px); }
.ac-revenue-product-field { position: relative; min-width: 0; padding: 21px clamp(16px, 1.8cqi, 30px) 16px; border-radius: 18px; background: var(--ac-revenue-field); color: #242236; }
.ac-revenue-field-label { display: flex; align-items: center; justify-content: space-between; margin: 0 2px 17px; color: #383252; font-size: 11px; }
.ac-revenue-field-label > span:last-child { font-size: 19px; line-height: .6; }
.ac-revenue-dashboard { position: relative; width: 100%; min-width: 0; border: 1px solid #b2aeeb; border-radius: 11px; background: #fff; color: #282839; box-shadow: 0 15px 35px #37316f1f, 0 2px 3px #37316f0a; }
.ac-revenue-app-bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 45px; padding: 10px 19px; border-bottom: 1px solid #eeedf5; }
.ac-revenue-app-bar > span:first-child { display: inline-flex; align-items: center; gap: 7px; font-size: 10px; color: #6d6c7a; }
.ac-revenue-app-bar svg { width: 17px; height: 17px; color: #6253e8; }
.ac-revenue-app-bar b { margin: 0 3px; color: #c4c1d0; font-weight: 400; }
.ac-revenue-preview-label { border: 1px solid #dedbea; border-radius: 4px; padding: 4px 6px; color: #706981; font-size: 8px; white-space: nowrap; }
.ac-revenue-app-content { padding: 20px 21px 5px; }
.ac-revenue-app-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; margin-bottom: 17px; }
.ac-revenue-app-heading p { margin-bottom: 5px; color: #85828f; font-size: 9px; }
.ac-revenue-app-heading h3 { color: #282839; font-size: 20px; font-weight: 500; letter-spacing: -.055em; line-height: 1.2; }
.ac-revenue-currency { padding: 4px 6px; border: 1px solid #eeedf5; border-radius: 4px; color: #726d82; font-size: 9px; }
.ac-revenue-controls { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 9px; }
.ac-revenue-range { display: inline-flex; gap: 2px; padding: 3px; border: 1px solid #eae8f2; border-radius: 6px; background: #f7f6fb; }
.ac-revenue-range button { min-height: 29px; border: 0; border-radius: 3px; padding: 4px 11px; color: #7d788e; background: transparent; font-size: 10px; line-height: 1.5; transition: background .16s ease; }
.ac-revenue-range button[aria-pressed="true"] { background: #fff; color: #322a57; box-shadow: 0 1px 3px #39304f1a; }
.ac-revenue-channel { position: relative; min-width: 0; max-width: 60%; }
.ac-revenue-channel select { appearance: none; max-width: 100%; min-height: 37px; padding: 7px 27px 7px 10px; border: 1px solid #eae8f2; border-radius: 6px; background: #fff; color: #5c576f; font-size: 10px; }
.ac-revenue-channel > svg { pointer-events: none; position: absolute; width: 12px; height: 12px; top: calc(50% - 6px); right: 9px; }
.ac-revenue-metrics { display: grid; grid-template-columns: 1.4fr .7fr 1fr; gap: 12px; margin: 19px 0 21px; }
.ac-revenue-metrics > div { min-width: 0; }
.ac-revenue-metrics > div + div { padding-left: 14px; border-left: 1px solid #eeedf5; }
.ac-revenue-metrics span { display: block; color: #85818e; font-size: 9px; line-height: 1.5; }
.ac-revenue-metrics strong { display: block; margin-top: 6px; color: #30283f; font-size: clamp(21px, 2.3cqi, 36px); font-weight: 500; letter-spacing: -.055em; line-height: 1.1; overflow-wrap: anywhere; }
.ac-revenue-metrics > div:not(:first-child) strong { font-size: clamp(17px, 1.6cqi, 25px); margin-top: 10px; }
.ac-revenue-chart-heading, .ac-revenue-transactions-heading { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 5px 12px; }
.ac-revenue-chart-heading h4, .ac-revenue-transactions-heading h4 { color: #61596f; font-size: 10px; font-weight: 500; }
.ac-revenue-chart-heading > span, .ac-revenue-transactions-heading > span { color: #898292; font-size: 9px; }
.ac-revenue-chart-wrap { display: grid; grid-template-columns: 38px minmax(0, 1fr); gap: 3px; margin-top: 15px; }
.ac-revenue-y-axis { display: flex; flex-direction: column; justify-content: space-between; height: 130px; padding: 0 0 1px; color: #a29baa; font-size: 8px; line-height: 1; }
.ac-revenue-chart { min-width: 0; }
.ac-revenue-chart > svg { display: block; width: 100%; height: 130px; overflow: visible; }
.ac-revenue-grid-line { stroke: #f0edf5; stroke-width: 1; vector-effect: non-scaling-stroke; }
.ac-revenue-chart-bar { fill: var(--ac-revenue-chart); }
.ac-revenue-chart-bar:hover { fill: #9386f9; }
.ac-revenue-x-axis { display: flex; justify-content: space-between; gap: 8px; margin-top: 8px; color: #9a93a2; font-size: 8px; }
.ac-revenue-transactions-heading { margin: 21px 0 9px; }
.ac-revenue-transaction-scroll { max-height: 160px; overflow: auto; scrollbar-width: thin; scrollbar-color: #dbd6e9 transparent; overscroll-behavior: contain; border-top: 1px solid #eeedf5; }
.ac-revenue-transactions { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 10px; }
.ac-revenue-transactions caption { text-align: left; }
.ac-revenue-transactions th, .ac-revenue-transactions td { padding: 10px 0; vertical-align: middle; text-align: left; }
.ac-revenue-transactions thead th { position: sticky; top: 0; z-index: 1; padding-top: 9px; padding-bottom: 9px; background: #fff; color: #9b93a5; font-size: 8px; font-weight: 400; }
.ac-revenue-transactions th:first-child { width: 52%; }
.ac-revenue-transactions th:nth-child(2) { width: 20%; }
.ac-revenue-transactions th:last-child, .ac-revenue-transactions td:last-child { text-align: right; }
.ac-revenue-transactions tbody tr { border-top: 1px solid #f4f1f7; }
.ac-revenue-transactions tbody th { display: flex; align-items: center; gap: 7px; width: auto !important; color: #4b415c; font-weight: 400; }
.ac-revenue-transactions tbody th > span:last-child { min-width: 0; overflow-wrap: anywhere; }
.ac-revenue-customer-avatar { display: grid; place-items: center; flex-shrink: 0; width: 25px; height: 25px; border: 1px solid #e8e3f4; border-radius: 6px; color: #81709b; background: #f9f6fe; font-size: 11px; font-weight: 600; }
.ac-revenue-transactions small { display: block; margin-top: 3px; color: #9b92a6; font-size: 8px; }
.ac-revenue-transactions td { color: #82768d; font-size: 9px; overflow-wrap: anywhere; }
.ac-revenue-transactions td:last-child { color: #645471; font-variant-numeric: tabular-nums; }
.ac-revenue-empty { padding: 22px 0 25px; color: #81748b; font-size: 11px; line-height: 1.6; }
.ac-revenue-sr { position: absolute !important; width: 1px !important; height: 1px !important; padding: 0 !important; margin: -1px !important; overflow: hidden !important; clip: rect(0, 0, 0, 0) !important; white-space: nowrap !important; border: 0 !important; }
.ac-revenue-action:focus-visible { outline: 2px solid white; outline-offset: 5px; }
.ac-revenue-dashboard:focus-visible { outline: 3px solid #5141bb; outline-offset: 5px; }
.ac-revenue-dashboard button:focus-visible, .ac-revenue-dashboard select:focus-visible, .ac-revenue-transaction-scroll:focus-visible { outline: 2px solid #6253e8; outline-offset: 2px; }
@container ac-revenue (min-width: 1600px) {
  .ac-revenue-masthead { min-height: 105px; }
  .ac-revenue-layout { grid-template-columns: minmax(0, .88fr) minmax(0, 1.12fr); }
  .ac-revenue-product-field { padding: 26px 34px 22px; }
  .ac-revenue-app-content { padding: 27px 29px 9px; }
  .ac-revenue-chart > svg, .ac-revenue-y-axis { height: 160px; }
  .ac-revenue-transaction-scroll { max-height: 180px; }
  .ac-revenue-transactions td, .ac-revenue-transactions tbody th { font-size: 11px; }
}
@container ac-revenue (max-width: 1000px) {
  .ac-revenue-masthead { min-height: 74px; }
  .ac-revenue-layout { grid-template-columns: minmax(0, 1fr); gap: 34px; }
  .ac-revenue-introduction { padding: 32px 0 4px; }
  .ac-revenue-introduction h2 { max-width: 12ch; font-size: clamp(48px, 8.6cqi, 78px); }
  .ac-revenue-description { max-width: 42ch; font-size: 15px; }
  .ac-revenue-product-field { padding: 20px 25px; }
  .ac-revenue-metrics strong { font-size: clamp(24px, 4cqi, 36px); }
  .ac-revenue-metrics > div:not(:first-child) strong { font-size: clamp(20px, 3.2cqi, 27px); }
  .ac-revenue-app-content { padding: 24px 26px 8px; }
  .ac-revenue-app-bar { padding-inline: 24px; }
  .ac-revenue-transactions td, .ac-revenue-transactions tbody th { font-size: 11px; }
}
@container ac-revenue (max-width: 520px) {
  .ac-revenue-hero-shell { padding: 0 19px 22px; }
  .ac-revenue-masthead { min-height: 69px; }
  .ac-revenue-brand { font-size: 23px; }
  .ac-revenue-masthead-label { font-size: 10px; }
  .ac-revenue-introduction { padding-top: 27px; }
  .ac-revenue-introduction h2 { max-width: 11ch; margin-top: 20px; margin-bottom: 20px; font-size: clamp(44px, 12.6cqi, 64px); }
  .ac-revenue-eyebrow { font-size: 10px; }
  .ac-revenue-description { max-width: 33ch; font-size: 14px; }
  .ac-revenue-action { margin-top: 24px; min-height: 46px; }
  .ac-revenue-product-field { margin-inline: -6px; padding: 16px 11px 15px; border-radius: 12px; }
  .ac-revenue-field-label { margin-bottom: 15px; font-size: 10px; }
  .ac-revenue-app-bar { min-height: 43px; padding-inline: 12px; }
